<script setup lang="ts">
import { onMounted, ref } from 'vue'
import { useRoute } from 'vue-router'
import { api, currency, formatDate } from '../services/api'
import type { Order } from '../types'
import LoadingState from '../components/LoadingState.vue'
const route=useRoute();const orders=ref<Order[]>([]);const loading=ref(true);const error=ref('');const busy=ref<string|null>(null);const message=ref('')
async function load(){loading.value=true;try{orders.value=await api.get<Order[]>('/api/v1/orders')}catch(e){error.value=e instanceof Error?e.message:'Gagal memuat pesanan'}finally{loading.value=false}}
async function pay(o:Order){busy.value=o.id;error.value='';try{const result=await api.post<{message:string}>('/api/v1/orders/'+o.id+'/pay',{});message.value=result.message;await load()}catch(e){error.value=e instanceof Error?e.message:'Pembayaran gagal'}finally{busy.value=null}}
async function cancel(o:Order){if(!confirm(`Batalkan pesanan ${o.order_number}?`))return;busy.value=o.id;try{await api.post('/api/v1/orders/'+o.id+'/cancel',{});await load()}catch(e){error.value=e instanceof Error?e.message:'Gagal membatalkan'}finally{busy.value=null}}
onMounted(load)
const statusLabels:Record<string,string>={pending_payment:'Menunggu pembayaran',processing:'Diproses',shipped:'Dikirim',delivered:'Selesai',cancelled:'Dibatalkan',expired:'Kedaluwarsa'}
</script>
<template><section class="page-intro"><p class="eyebrow">RIWAYAT TRANSAKSI</p><h1>Pesanan saya</h1><p>Pantau status pesanan dan lakukan pembayaran demo untuk pesanan yang belum dibayar.</p></section><p v-if="route.query.new" class="success-banner">Pesanan berhasil dibuat. Selesaikan pembayaran simulasi di bawah.</p><p v-if="message" class="success-banner">{{ message }}</p><p v-if="error" class="error-banner">{{ error }}</p><LoadingState v-if="loading"/><div v-else-if="orders.length" class="orders-list"><article v-for="o in orders" :key="o.id" class="order-card"><div class="order-head"><div><span class="eyebrow">{{ formatDate(o.created_at) }}</span><h3>{{ o.order_number }}</h3></div><span class="status-pill" :class="'status-'+o.status">{{ statusLabels[o.status]??o.status }}</span></div><div class="order-items-preview"><div v-for="item in o.items" :key="item.id" class="mini-order-item"><img :src="item.image_url" :alt="item.product_name"/><div><strong>{{ item.product_name }}</strong><small>{{ item.quantity }} × {{ currency(item.unit_price) }}</small></div><strong>{{ currency(item.line_total) }}</strong></div></div><div class="order-foot"><div><small class="muted">Total pesanan</small><strong class="order-total">{{ currency(o.total) }}</strong><small class="muted">Pembayaran: {{ o.payment_status }}</small><small v-if="o.tracking_number" class="muted">Resi: {{ o.tracking_number }}</small></div><div class="order-actions"><button v-if="o.status==='pending_payment'" class="button-primary" :disabled="busy===o.id" @click="pay(o)">{{ busy===o.id?'Memproses…':'Bayar (simulasi)' }}</button><button v-if="o.status==='pending_payment'" class="button-secondary" :disabled="busy===o.id" @click="cancel(o)">Batalkan</button></div></div></article></div><div v-else class="empty-state"><h3>Belum ada pesanan</h3><p>Pesanan yang kamu buat akan tampil di sini.</p><RouterLink to="/products" class="button-primary">Mulai belanja</RouterLink></div></template>
